    "images_tried": ["python:2.7"],
    "image_used": "python:2.7",
    "pull_success": true,
    "run_command": "docker run --rm -v /tmp/tdlm:/repo -w /repo python:2.7 bash -c \"pip install -q 'tensorflow==0.12.1' 'gensim==0.13.4' 'numpy<1.17' 'scipy<1.3'; python tdlm_train.py; python tdlm_test.py -m output/toy-model/ -d data/toy-valid.txt --print_perplexity\""
  },
  "install": {
    "status": "success",
    "log_tail": "pip install tensorflow==0.12.1 gensim==0.13.4 numpy<1.17 scipy<1.3 成功;python -c 'import tensorflow,gensim' -> ('0.12.1', '0.13.4')"
  },
  "run": {
    "command": "python tdlm_train.py && python tdlm_test.py -m output/toy-model/ -d data/toy-valid.txt --print_perplexity",
    "status": "success",
    "output_tail": "Epoch = 0\\nTRAIN 1/141: tm ppl = 2785.864; lm ppl = 1.000; word/sec = 2332.8 ... TRAIN 141/141: tm ppl = 2578.378; lm ppl = 2222.765\\nVALID 27/27: tm ppl = 2144.436; lm ppl = 893.853\\n=== TEST ===\\ntest topic model perplexity = 2144.436\\ntest language model perplexity = 893.854\\n(并成功输出 topics 与按主题生成的句子)",
    "speed": "toy 配置(hidden=60, k=10, 1 epoch)141 步总耗时约 10s(含评测/生成),约 17000 word/sec(CPU)。论文配置 hidden=600/900、k=100、数据量为 AP News/BNC/IMDB 全量,数量级远大于 toy"
  },
  "smoke_verdict": "smoke_passed_toy",
  "all_blockers": [
    {
      "verdict": "blocked_data_link_dead",
      "confirmed_by": "static",
      "detail": "README 提供的论文数据集下载地址 https://ibm.box.com/s/ls61p8ovc1y87w45oa02zink2zl7l6z4 已失效(curl 返回 HTTP/2 404),仓库未提供其他来源。替代思路:IMDB 可用 Maas et al. 原始语料自行按仓库格式预处理;APNEWS 需 LDC/新闻授权;BNC 需签许可协议 —— 因此即使找到替代也无法保证与论文同一预处理版本。"
    },
    {
      "verdict": "blocked_data_licensed",
      "confirmed_by": "static",
      "detail": "BNC 语料本身需签署使用协议,无法自动获取。"
    }
  ],
  "blocker_attribution": "genuine",
  "verdict_reason": "代码在 python:2.7 + tensorflow 0.12.1 容器中依赖装得上、用仓库自带 toy 数据完整跑通训练与评测,但论文真实数据集下载链接已 404 且无法确认同版本替代。",
  "repro": {
    "status": "skipped",
    "skip_reason": "smoke test 使用的是 toy 数据(真实数据集链接 404),按流程不做限时复现与数字比较",
    "estimated_minutes": null,
    "command": null,
    "metric": null,
    "our_value": null,
    "paper_value": null,
    "paper_source": null,
    "match": null,
    "note": "toy 数据上的 ppl(TM 2144 / LM 894)与论文 Table 中 APNEWS/BNC/IMDB 的困惑度不具可比性"
  }
}
```

